package com.bananalab.lite;
import android.app.*;import android.os.*;import android.content.*;import java.io.*;
/** Separate private process, not a security sandbox for arbitrary Java. */
public final class JavaTrialService extends Service{
 final Messenger messenger=new Messenger(new Handler(){@Override public void handleMessage(Message message){Bundle out=new Bundle();try{String expression=message.getData().getString("expression"),path=message.getData().getString("jar");File file=new File(path);if(!file.getCanonicalPath().startsWith(OnDeviceJava.home(JavaTrialService.this).getCanonicalPath()+File.separator)||!file.isFile()||file.canWrite())throw new IOException("Archivo de prueba inválido.");if(message.getData().getString("kind", "curve").equals("pipeline")){org.json.JSONObject spec=new org.json.JSONObject(expression);ProgramPlan plan=ProgramPlan.read(spec.getJSONObject("plan"));Class<?> type=OnDeviceJava.load(JavaTrialService.this,file).getClassLoader().loadClass("com.bananalab.patch.ProgramKernel");org.json.JSONObject report=ProgramJudge.check(type.getMethod("apply",String.class),plan,spec.getLong("seed"));out.putInt("samples",64);out.putString("report",report.toString());}else if(message.getData().getString("kind", "curve").equals("understanding")){org.json.JSONObject spec=new org.json.JSONObject(expression);UnderstandingSpec.read(spec.getJSONObject("before"));UnderstandingSpec.read(spec.getJSONObject("after"));CapabilityBench.validateUser(spec.getJSONArray("cases"));ClassLoader loader=OnDeviceJava.load(JavaTrialService.this,file).getClassLoader();org.json.JSONObject report=CapabilityBench.evaluate(loader.loadClass("com.bananalab.patch.UnderstandingBaseline").getMethod("rewrite",String.class),loader.loadClass("com.bananalab.patch.UnderstandingCandidate").getMethod("rewrite",String.class),spec.getLong("seed"),spec.getJSONArray("cases"));out.putInt("samples",report.getInt("total"));out.putString("report",report.toString());}else if(message.getData().getString("kind", "curve").equals("method")){org.json.JSONObject spec=new org.json.JSONObject(expression);MethodProgram program=MethodProgram.read(spec.getJSONObject("program")),goal=MethodProgram.read(spec.getJSONObject("goal"));Class<?> cls=OnDeviceJava.load(JavaTrialService.this,file).getClassLoader().loadClass("com.bananalab.patch.JavaMethodCandidate");out.putInt("samples",MethodProgram.check(cls.getMethod("run",String.class),goal));}else if(message.getData().getString("kind", "curve").equals("project")){out.putInt("samples",ProjectReplacementSpec.check(JavaTrialService.this,file,new org.json.JSONObject(expression)));}else if(message.getData().getString("kind", "curve").equals("text")){JavaTextPlan plan=JavaTextPlan.read(expression);int count=JavaMethodEditor.check(JavaMethodEditor.method(JavaTrialService.this,path),plan);out.putInt("samples",count);}else{JavaCurve curve=new JavaCurve(expression);Class<?> cls=OnDeviceJava.load(JavaTrialService.this,file).getClassLoader().loadClass("com.bananalab.patch.BananaFunction");java.lang.reflect.Method method=cls.getMethod("jump",float.class);for(int i=0;i<=256;i++){float t=i/256f,actual=((Number)method.invoke(null,t)).floatValue();if(Float.isNaN(actual)||Float.isInfinite(actual)||Math.abs(actual-curve.value(t))>.001f)throw new IOException("La función compilada no coincide con la fórmula.");}out.putInt("samples",257);}
 out.putBoolean("ok",true);out.putInt("pid",android.os.Process.myPid());}catch(Throwable e){out.putString("error",e.getClass().getSimpleName()+": "+e.getMessage());}try{Message response=Message.obtain();response.setData(out);message.replyTo.send(response);}catch(Exception ignored){}}});
 @Override public IBinder onBind(Intent intent){return messenger.getBinder();}
}
